-- ============================================================================
-- IFA 演示数据（仅用于本地演示库 / SQLite）
-- ----------------------------------------------------------------------------
-- 用途：让 README「界面展示」的截图对得上 —— 产品 60 条、报警 20 条、
--       审计记录 40 条 + 字段变更 11 条。数据全为虚构演示值
--       （操作员 张伟 / 李强 / 王芳，设备 ZYKJ-01 / ZYKJ-02），不含真实产线与客户。
--
-- 前置：先启动一次程序，让 CodeFirst 建好空表，再执行本脚本。
--       空库直接跑会因表不存在而失败。
--
-- 执行：DB Browser for SQLite 打开 Data/tyl_ifa.db → 执行 SQL
--       或命令行：sqlite3 Data/tyl_ifa.db < tools/seed-demo.sql
--
-- 影响范围（会删数据，别对生产库执行）：
--   product_cellinfo         全表清空，重插 60 条
--   sys_alarm_records        全表清空，重插 20 条
--   sys_audit_operations     删除 Id >= 14 的行，重插 14~40
--   sys_audit_field_changes  删除 OperationId >= 14 的行，重插 11 条
--   其余表不动；Id 1~13 的审计种子数据保留
--
-- 方言：SQLite（MySQL / SQL Server 需自行调整自增列与列名大小写）。
-- ============================================================================

-- IFA 演示数据：产品采集记录 60 条（2026-11-05 08:00-15:30）
DELETE FROM product_cellinfo;

-- ============ 报警记录 20 条（三态：提示 6 / 警告 8 / 异常 6）============
DELETE FROM sys_alarm_records;

-- ============ 审计记录补 27 条（总 40 条）============
DELETE FROM sys_audit_field_changes WHERE OperationId >= 14;
DELETE FROM sys_audit_operations WHERE Id >= 14;


-- ============ 审计字段变更 11 条 ============
